CREATE TABLE IF NOT EXISTS admins (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(191) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS employees (id INT AUTO_INCREMENT PRIMARY KEY, employee_id VARCHAR(191) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL, username VARCHAR(191), email VARCHAR(255), phone VARCHAR(50), designation VARCHAR(255), password VARCHAR(255) NOT NULL, dob VARCHAR(32), join_date VARCHAR(32), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS contacts (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255), email VARCHAR(255), phone VARCHAR(50), message TEXT, source VARCHAR(100) DEFAULT 'contact', status VARCHAR(50) NOT NULL DEFAULT 'new', assigned_employee_id INT NULL, notes TEXT, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX (assigned_employee_id), FOREIGN KEY (assigned_employee_id) REFERENCES employees(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS projects (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(255), description TEXT, image VARCHAR(500), category VARCHAR(100), client VARCHAR(255), technologies TEXT, project_url VARCHAR(500), slug VARCHAR(191) UNIQUE, industry VARCHAR(100), results TEXT);
CREATE TABLE IF NOT EXISTS blogs (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(255), content LONGTEXT, author VARCHAR(255), image VARCHAR(500), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS jobs (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(255), location VARCHAR(255), experience VARCHAR(255), description TEXT);
CREATE TABLE IF NOT EXISTS job_applications (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255), email VARCHAR(255), phone VARCHAR(50), current_company VARCHAR(255), current_salary VARCHAR(100), expected_salary VARCHAR(100), experience VARCHAR(100), notice_period VARCHAR(100), resume VARCHAR(500), message TEXT, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS internship_applications (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255), email VARCHAR(255), phone VARCHAR(50), internship_type VARCHAR(255), college VARCHAR(255), course VARCHAR(255), resume VARCHAR(500), message TEXT, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS chatbot_settings (id INT PRIMARY KEY, data LONGTEXT);
CREATE TABLE IF NOT EXISTS attendance (id INT AUTO_INCREMENT PRIMARY KEY, employee_id INT NOT NULL, date DATE NOT NULL, punch_in DATETIME NULL, punch_out DATETIME NULL, punch_in_location VARCHAR(255), punch_out_location VARCHAR(255), UNIQUE KEY attendance_unique (employee_id, date), FOREIGN KEY (employee_id) REFERENCES employees(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS leave_requests (id INT AUTO_INCREMENT PRIMARY KEY, employee_id INT NOT NULL, from_date DATE, to_date DATE, reason TEXT, status VARCHAR(50) NOT NULL DEFAULT 'pending', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (employee_id) REFERENCES employees(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS announcements (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(255), content TEXT, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS greetings (id INT AUTO_INCREMENT PRIMARY KEY, from_employee_id INT NOT NULL, to_employee_id INT NOT NULL, occasion VARCHAR(255), message TEXT, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (from_employee_id) REFERENCES employees(id) ON DELETE CASCADE, FOREIGN KEY (to_employee_id) REFERENCES employees(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS conversations (id INT AUTO_INCREMENT PRIMARY KEY, type VARCHAR(50) NOT NULL, name VARCHAR(255), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS conversation_participants (id INT AUTO_INCREMENT PRIMARY KEY, conversation_id INT NOT NULL, employee_id INT NOT NULL, UNIQUE KEY conversation_participant_unique (conversation_id, employee_id), FOREIGN KEY (conversation_id) REFERENCES conversations(id) ON DELETE CASCADE, FOREIGN KEY (employee_id) REFERENCES employees(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS conversation_messages (id INT AUTO_INCREMENT PRIMARY KEY, conversation_id INT NOT NULL, from_employee_id INT NOT NULL, message TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (conversation_id) REFERENCES conversations(id) ON DELETE CASCADE, FOREIGN KEY (from_employee_id) REFERENCES employees(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS testimonials (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255) NOT NULL, company VARCHAR(255), designation VARCHAR(255), rating INT NOT NULL DEFAULT 5, text TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, sort_order INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS services (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(255) NOT NULL, slug VARCHAR(191) NOT NULL UNIQUE, description TEXT, icon VARCHAR(255), active BOOLEAN NOT NULL DEFAULT TRUE, sort_order INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS about_journey (id INT AUTO_INCREMENT PRIMARY KEY, journey_year YEAR NOT NULL UNIQUE, title VARCHAR(255) NOT NULL, description TEXT NOT NULL, sort_order INT NOT NULL DEFAULT 0);